/// `delta=200ms < DELTA=250ms` lands after the skip -> F1 is a bug.
#[test]
fn f1_premature_skip_within_declared_synchrony_bound() {
    use crate::common::{DELTA, DELTA_TIMEOUT};
    use solana_clock::DEFAULT_MS_PER_SLOT;

    let delta_block = Duration::from_millis(DEFAULT_MS_PER_SLOT); // 400ms — production slot time
    let delta_timeout = DELTA_TIMEOUT;                            // 400ms — common.rs:29
    let delta_declared = DELTA;                                   // 250ms — common.rs:21, declared bound

    // Actual network delay INSIDE the code's declared synchrony bound.
    let delta_actual = Duration::from_millis(200);                // 200ms < DELTA=250ms
    // Whitepaper v1.1 line 1076 arrival model: 3*delta + delta_block.
    let block_arrival = delta_actual * 3 + delta_block;           // 3*200 + 400 = 1000ms

    let now = Instant::now();
    let timeout_config = TimeoutConfig {
        delta_timeout,
        delta_first_fec_set: delta_block, // event_handler.rs:238: delta_first_fec_set = delta_block
        delta_block,
    }
    .scaled(0, None);
    let (mut timer_state, first_fire) = TimerState::new(0, timeout_config, now);

    // MEASURED (real state machine): skip deadline = delta_timeout + delta_block = 800ms.
    let skip_deadline = now + delta_timeout + delta_block;
    assert_eq!(first_fire, skip_deadline, "first fire scheduled at delta_timeout+delta_block");
    assert_eq!(
        skip_deadline.duration_since(now).as_millis(),
        800,
        "skip deadline is 800ms (DELTA_TIMEOUT=400 + delta_block=400)"
    );

    // TimeoutCrashedLeader(0) fires at the 800ms deadline.
    assert!(matches!(
        timer_state.progress(skip_deadline).unwrap(),
        VotorEvent::TimeoutCrashedLeader(0)
    ));
    // Timeout(0) — the per-slot SKIP — fires at the same 800ms (delta_first_fec_set == delta_block).
    assert!(matches!(
        timer_state
            .progress(timer_state.next_fire().unwrap())
            .unwrap(),
        VotorEvent::Timeout(0)
    ));

    // IMPACT: under the code's OWN declared synchrony bound (delta_actual=200ms < DELTA=250ms),
    // the honest leader's block arrives at 1000ms — AFTER the 800ms skip. Premature skip.
    assert!(
        block_arrival > skip_deadline,
        "block arrival {}ms (delta={}ms, within declared DELTA={}ms) must be AFTER skip deadline {}ms",
        block_arrival.as_millis(),
        delta_actual.as_millis(),
        delta_declared.as_millis(),
        skip_deadline.duration_since(now).as_millis(),
    );

    // Boundary check: the threshold is delta > DELTA_TIMEOUT/3 ~= 133ms. At delta=133ms arrival
    // == skip; above 133ms (and up to the declared 250ms) the leader is prematurely skipped.
    let threshold = delta_timeout / 3; // ~133ms
    assert!(delta_actual > threshold, "delta=200ms is above the ~133ms premature-skip threshold");
    assert!(delta_actual <= delta_declared, "delta=200ms is within the declared DELTA=250ms bound");
    // => For delta in (133ms, 250ms] the skip fires before the block arrives, inside the code's
    //    own stated synchrony assumption. F1 reproduced.
}

